-- Advanced local workflow controls; no direct gameplay calls.
return function(app,label,button,field,secretField)
    field('SETTINGS','Named preference profile','profileName',false)
    button('SETTINGS','SAVE NAMED PROFILE + BACKUP',function() app:saveProfile() end)
    button('SETTINGS','LOAD NAMED PROFILE • AUTO OFF',function() app:loadProfile() end)
    button('SETTINGS','IMPORT PORTABLE SETTINGS FROM CLIPBOARD',function() app:importSettings() end)
    button('SETTINGS','RESET PREFERENCES • SPENDING LEDGER RETAINED',function() app:applyPortableSettings({schema=1,settings={}}) end)
    button('SETTINGS',function() return 'LOCAL QUALITY: '..app.cfg.qualityProfile end,function() app:cycle('qualityProfile',{'Normal','Low'}) end)
    label('SETTINGS','Low quality reversibly disables observed Lighting effects and shadows. It preserves terrain and paths. Device FPS gains are unmeasured.')
    button('SETTINGS',function() return 'BLACK SCREEN OVERLAY: '..tostring(app.cfg.blackScreen) end,function() app:toggle('blackScreen') end)
    label('SETTINGS','Black overlay hides the game view and keeps our Stop/restore controls visible. It does not claim to disable 3D rendering.')
    button('SETTINGS',function() return 'OPTIONAL ANTI-AFK WHILE AUTO RUNS: '..tostring(app.cfg.antiAfk) end,function() app:toggle('antiAfk') end)
    button('SETTINGS',function() return 'THEME: '..app.cfg.uiTheme end,function() app:cycle('uiTheme',{'Dark','Midnight','OLED'}) end)
    field('SETTINGS','UI scale (0.75–1.25)','uiScale',true)
    field('SETTINGS','Local camera maximum zoom (0 restores original)','cameraZoom',true)
    button('SETTINGS',function() return 'NATIVE SCREEN: '..app.cfg.nativeScreen end,function() app:cycle('nativeScreen',{'collection','items','SummonGUI','TraitReroll','StatReroll'}) end)
    button('SETTINGS','OPEN SELECTED EXISTING GAME SCREEN',function() app:openNativeScreen() end)
    label('SETTINGS',function() return tostring(app.localStatus or 'Local optimizers are inactive') end)
    if secretField then secretField('SETTINGS','Webhook URL (session only; excluded from exports)',function(value) app:configureWebhook(value) end) end
    button('SETTINGS',function() return 'OPTIONAL MATCH/CHEST NOTIFICATIONS: '..tostring(app.notificationEnabled==true) end,function() app:toggleNotifications() end)
    button('SETTINGS','SEND ONE WEBHOOK TEST',function() app:testNotification() end)
    label('SETTINGS',function() return 'Notification transport: '..app.reports.notificationState end)
    label('REPORTS',function() return app.reports:render(4000) end)
    button('REPORTS','RESET RETAINED REPORT TOTALS • DOES NOT RESET LIMITS',function() app:resetReportTotals() end)
    label('REPORTS',function() return app:featureStatusText() end)
end
